from collections import Counter

class Solution:
    def maxPalindromesAfterOperations(self, words: list[str]) -> int:
        cnt = Counter(''.join(words))
        pairs = sum(c // 2 for c in cnt.values())
        lengths = sorted(len(w) for w in words)
        ans = 0
        for l in lengths:
            need = l // 2
            if pairs >= need:
                pairs -= need
                ans += 1
            else:
                break
        return ans

#include <vector>
#include <string>
#include <algorithm>

class Solution {
public:
    int maxPalindromesAfterOperations(std::vector<std::string>& words) {
        std::vector<int> cnt(26, 0);
        std::vector<int> lengths;
        for (const auto& w : words) {
            lengths.push_back(w.size());
            for (char ch : w) cnt[ch - 'a']++;
        }
        std::sort(lengths.begin(), lengths.end());
        int pairs = 0;
        for (int c : cnt) pairs += c / 2;
        int ans = 0;
        for (int l : lengths) {
            int need = l / 2;
            if (pairs >= need) {
                pairs -= need;
                ans++;
            } else break;
        }
        return ans;
    }
};

import java.util.Arrays;

class Solution {
    public int maxPalindromesAfterOperations(String[] words) {
        int[] cnt = new int[26];
        int[] lengths = new int[words.length];
        for (int i = 0; i < words.length; ++i) {
            lengths[i] = words[i].length();
            for (char ch : words[i].toCharArray()) cnt[ch - 'a']++;
        }
        Arrays.sort(lengths);
        int pairs = 0;
        for (int c : cnt) pairs += c / 2;
        int ans = 0;
        for (int l : lengths) {
            int need = l / 2;
            if (pairs >= need) {
                pairs -= need;
                ans++;
            } else break;
        }
        return ans;
    }
}

var maxPalindromesAfterOperations = function(words) {
    const cnt = new Array(26).fill(0);
    const lengths = [];
    for (const w of words) {
        lengths.push(w.length);
        for (const ch of w) cnt[ch.charCodeAt(0) - 97]++;
    }
    lengths.sort((a, b) => a - b);
    let pairs = 0;
    for (const c of cnt) pairs += Math.floor(c / 2);
    let ans = 0;
    for (const l of lengths) {
        const need = Math.floor(l / 2);
        if (pairs >= need) {
            pairs -= need;
            ans++;
        } else break;
    }
    return ans;
};
